  @Test("hexdump output matches the system hexdump", arguments: systemCases)
  func matchesSystemHexdump(_ args: [String], _ stdinFile: String?, _ expected: String, _ status: Int) async throws {
    let dir = HexdumpFixture.dir
    var stdin: [UInt8]? = nil
    if let stdinFile {
      stdin = try dir.appending(stdinFile).readAllBytes()
    }
    try await run(withStdin: stdin, status: status, output: expected, args: args, env: ["LC_ALL": "C"], cd: dir)
  }

